package cn.zhuatech.pricingai.controller; import cn.zhuatech.pricingai.common.ApiResponse; import cn.zhuatech.pricingai.dto.PricingAiDto.*; import cn.zhuatech.pricingai.service.PricingAiService; import cn.zhuatech.pricingai.service.AiRiskAssessmentService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('DOMAIN_USER','ADMIN')") public class WorkspaceController {private final PricingAiService service;private final AiRiskAssessmentService risk;public WorkspaceController(PricingAiService service,AiRiskAssessmentService risk){this.service=service;this.risk=risk;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("定价审核反馈已提交",service.report(id,request));}@PostMapping("/ai-risk-assessment") public ApiResponse<AiRiskAssessmentService.Result> assess(@Valid @RequestBody AiRiskAssessmentService.Request request){return ApiResponse.ok("AI 风险评估完成",risk.assess(request));}}
